mapper.select:
SELECT d.id AS id, d.imei AS imei, d.status AS status, d.product_id AS productId, d.first_seen_at AS firstSeenAt, d.last_seen_at AS lastSeenAt, dvp.version AS version, dvp.internal_version AS internalVersion FROM devices d JOIN device_version_parts dvp ON dvp.device_id = d.id AND dvp.is_primary = 1 AND dvp.version_id = #{versionId}
d.id > #{cursor}
AND d.imei LIKE CONCAT('%', #{keyword}, '%')
ORDER BY d.id ASC LIMIT #{size}

SELECT d.id AS id, d.imei AS imei, d.status AS status, d.product_id AS productId, d.first_seen_at AS firstSeenAt, d.last_seen_at AS lastSeenAt, dvp.version_id AS versionId, COALESCE(dvp.version, fv.version, 'UNKNOWN') AS version, COALESCE(dvp.internal_version, fv.internal_version) AS internalVersion FROM devices d LEFT JOIN device_version_parts dvp ON dvp.device_id = d.id AND dvp.is_primary = 1 LEFT JOIN firmware_versions fv ON fv.id = dvp.version_id AND fv.deleted = 0 WHERE d.product_id = #{productId}
AND d.id > #{cursor}
AND d.imei LIKE CONCAT('%', #{keyword}, '%')
ORDER BY d.id ASC LIMIT #{size}
